insert into public.campaign_regions (id, name, sort_order, content_version) values
  ('sinnoh', 'Sinnoh', 1, 2)
insert into public.campaign_nodes (id, region_id, sort_order, kind, title, summary, npc_name, encounter_kind, encounter_difficulty, required_victories, repeatable) values
  ('sinnoh.twinleaf-town', 'sinnoh', 1, 'story', 'Twinleaf Town', 'Sua jornada começa em casa. Dê o primeiro passo para sair da cidade.', null, 'milestone', 1, 1, false),
  ('sinnoh.route-201', 'sinnoh', 2, 'route', 'Rota 201', 'Grama alta e os primeiros Pokémon selvagens no caminho para Sandgem.', null, 'wild', 1, 3, true),
  ('sinnoh.rival-route-201', 'sinnoh', 3, 'rival', 'Primeiro duelo com o rival', 'Barry está sempre com pressa — e quer testar o Pokémon dele contra o seu.', 'Barry', 'rival', 2, 1, false),
  ('sinnoh.lake-verity', 'sinnoh', 4, 'story', 'Lake Verity', 'Na beira do lago, um homem de olhar frio fala sozinho sobre tempo e espaço.', null, 'milestone', 1, 1, false),
  ('sinnoh.sandgem-town', 'sinnoh', 5, 'story', 'Sandgem Town', 'O Professor Rowan confia a você a Pokédex e uma tarefa: registrar toda Sinnoh.', null, 'milestone', 1, 1, false),
  ('sinnoh.route-202', 'sinnoh', 6, 'route', 'Rota 202', 'O caminho até Jubilife, cheio de treinadores iniciantes e Pokémon novos.', null, 'wild', 1, 3, true),
  ('sinnoh.jubilife-city', 'sinnoh', 7, 'story', 'Jubilife City', 'A maior cidade até aqui. Os alunos da Escola de Treinadores querem batalhar.', null, 'trainer', 1, 2, false),
  ('sinnoh.rival-route-203', 'sinnoh', 8, 'rival', 'Revanche na Rota 203', 'Barry treinou desde o último encontro e bloqueia o caminho para Oreburgh.', 'Barry', 'rival', 2, 1, false),
  ('sinnoh.oreburgh-gate', 'sinnoh', 9, 'route', 'Oreburgh Gate', 'Uma caverna curta separa você da cidade mineradora de Oreburgh.', null, 'wild', 1, 2, true),
  ('sinnoh.oreburgh-mine', 'sinnoh', 10, 'route', 'Oreburgh Mine', 'O líder do ginásio não está no ginásio: está no fundo da mina, cavando.', null, 'wild', 2, 2, true),
  ('sinnoh.oreburgh-gym', 'sinnoh', 11, 'gym', 'Ginásio de Oreburgh', 'Roark, especialista em Pokémon de pedra, guarda a primeira insígnia de Sinnoh.', 'Roark', 'gymLeader', 3, 1, false),
  ('sinnoh.jubilife-galactic', 'sinnoh', 12, 'story', 'Emboscada em Jubilife', 'Dois capangas de uniforme prateado cercam o Professor Rowan. Hora de ajudar.', null, 'trainer', 2, 1, false),
  ('sinnoh.route-204', 'sinnoh', 13, 'route', 'Rota 204', 'Campos floridos ao norte de Jubilife, cortados por um paredão de pedra.', null, 'wild', 2, 3, true),
  ('sinnoh.ravaged-path', 'sinnoh', 14, 'route', 'Ravaged Path', 'Um túnel estreito e úmido atravessa o paredão da Rota 204.', null, 'wild', 2, 2, true),
  ('sinnoh.floaroma-town', 'sinnoh', 15, 'story', 'Floaroma Town', 'A cidade das flores. Uma menina pede ajuda: o pai dela está preso na usina.', null, 'milestone', 1, 1, false),
  ('sinnoh.valley-windworks', 'sinnoh', 16, 'story', 'Valley Windworks', 'A Equipe Galáctica tomou a usina eólica. A comandante Mars não pretende sair.', 'Mars', 'trainer', 3, 1, false),
  ('sinnoh.route-205', 'sinnoh', 17, 'route', 'Rota 205', 'Pontes de madeira e pescadores no caminho para a floresta de Eterna.', null, 'wild', 2, 3, true),
  ('sinnoh.eterna-forest', 'sinnoh', 18, 'route', 'Eterna Forest', 'Uma floresta densa e fácil de se perder. Cheryl pede companhia até a saída.', null, 'wild', 2, 3, true),
  ('sinnoh.eterna-city', 'sinnoh', 19, 'story', 'Eterna City', 'Uma cidade antiga, com uma estátua gasta de um Pokémon que ninguém sabe nomear.', null, 'milestone', 2, 1, false),
  ('sinnoh.eterna-gym', 'sinnoh', 20, 'gym', 'Ginásio de Eterna', 'Gardenia cuida de um ginásio que parece um jardim — e os Pokémon de planta dela mordem.', 'Gardenia', 'gymLeader', 3, 1, false),
  ('sinnoh.galactic-eterna-building', 'sinnoh', 21, 'story', 'Prédio Galáctico de Eterna', 'O prédio estranho ao norte da cidade esconde Pokémon roubados e a comandante Jupiter.', 'Jupiter', 'trainer', 3, 1, false),
  ('sinnoh.route-206', 'sinnoh', 22, 'route', 'Rota 206 — Cycling Road', 'Uma ladeira longa de bicicleta, com ciclistas querendo batalhar o tempo todo.', null, 'trainer', 2, 3, true),
  ('sinnoh.wayward-cave', 'sinnoh', 23, 'route', 'Wayward Cave', 'Uma caverna escura sob a Cycling Road, onde é fácil perder o rumo.', null, 'wild', 2, 2, true),
  ('sinnoh.route-207', 'sinnoh', 24, 'route', 'Rota 207', 'Encostas de terra solta ao pé do Monte Coronet.', null, 'wild', 2, 2, true),
  ('sinnoh.mt-coronet-south', 'sinnoh', 25, 'story', 'Mt. Coronet', 'Dentro da montanha, o homem do lago reaparece e fala da origem do mundo.', null, 'milestone', 2, 1, false),
  ('sinnoh.route-208', 'sinnoh', 26, 'route', 'Rota 208', 'Pontes sobre o desfiladeiro e, do outro lado, as luzes de Hearthome.', null, 'wild', 3, 3, true),
  ('sinnoh.hearthome-city', 'sinnoh', 27, 'story', 'Hearthome City', 'Cidade de concursos e parques. A líder do ginásio também é estrela dos palcos.', null, 'milestone', 2, 1, false),
  ('sinnoh.hearthome-gym', 'sinnoh', 28, 'gym', 'Ginásio de Hearthome', 'Fantina e seus Pokémon fantasmas transformam a batalha em espetáculo.', 'Fantina', 'gymLeader', 3, 1, false),
  ('sinnoh.rival-hearthome', 'sinnoh', 29, 'rival', 'Barry em Hearthome', 'Mal você sai do ginásio, Barry esbarra em você exigindo uma batalha.', 'Barry', 'rival', 3, 1, false),
  ('sinnoh.route-209', 'sinnoh', 30, 'route', 'Rota 209', 'Um rio calmo, uma torre de pedra ao longe e muitos treinadores no caminho.', null, 'wild', 3, 3, true),
  ('sinnoh.lost-tower', 'sinnoh', 31, 'route', 'Lost Tower', 'Uma torre silenciosa onde treinadores vêm se despedir de seus Pokémon.', null, 'trainer', 3, 2, true),
  ('sinnoh.solaceon-town', 'sinnoh', 32, 'story', 'Solaceon Town', 'Uma vila tranquila com ruínas cobertas de símbolos que parecem letras.', null, 'milestone', 2, 1, false),
  ('sinnoh.route-210-south', 'sinnoh', 33, 'route', 'Rota 210 — Sul', 'Capim alto até um café de beira de estrada. Um bando de Psyduck trava a passagem norte.', null, 'wild', 3, 2, true),
  ('sinnoh.route-215', 'sinnoh', 34, 'route', 'Rota 215', 'Chove sem parar nesta rota, e os lutadores que treinam nela não se importam.', null, 'trainer', 3, 3, true),
  ('sinnoh.veilstone-city', 'sinnoh', 35, 'story', 'Veilstone City', 'Cidade erguida na rocha, com meteoritos antigos e um prédio enorme da Equipe Galáctica.', null, 'milestone', 2, 1, false),
  ('sinnoh.veilstone-gym', 'sinnoh', 36, 'gym', 'Ginásio de Veilstone', 'Maylene luta descalça e treina mais do que qualquer um. Os Pokémon lutadores dela também.', 'Maylene', 'gymLeader', 4, 1, false),
  ('sinnoh.galactic-warehouse', 'sinnoh', 37, 'story', 'Armazém Galáctico', 'Capangas roubaram a Pokédex do assistente do professor. Vocês dois vão buscá-la.', null, 'trainer', 3, 1, false),
  ('sinnoh.route-214', 'sinnoh', 38, 'route', 'Rota 214', 'Uma estrada cercada de mato que desce em direção ao Lago Valor.', null, 'wild', 3, 3, true),
  ('sinnoh.valor-lakefront', 'sinnoh', 39, 'story', 'Valor Lakefront', 'A entrada do lago está bloqueada. Há um hotel de luxo e pouca explicação.', null, 'milestone', 3, 1, false),
  ('sinnoh.route-213', 'sinnoh', 40, 'route', 'Rota 213', 'Praia, mar aberto e nadadores prontos para uma batalha.', null, 'wild', 3, 2, true),
  ('sinnoh.great-marsh', 'sinnoh', 41, 'route', 'Great Marsh de Pastoria', 'Um pântano enorme onde vivem Pokémon que não aparecem em nenhum outro lugar.', null, 'wild', 3, 3, true),
  ('sinnoh.pastoria-gym', 'sinnoh', 42, 'gym', 'Ginásio de Pastoria', 'Crasher Wake é lutador mascarado, barulhento e mestre dos Pokémon de água.', 'Crasher Wake', 'gymLeader', 4, 1, false),
  ('sinnoh.rival-pastoria', 'sinnoh', 43, 'rival', 'Barry em Pastoria', 'Barry quer provar que a insígnia dele vale mais do que a sua.', 'Barry', 'rival', 3, 1, false),
  ('sinnoh.galactic-chase', 'sinnoh', 44, 'story', 'Perseguição até o lago', 'Um capanga foge de Pastoria falando em bomba. Você o alcança em Valor Lakefront.', null, 'trainer', 3, 1, false),
  ('sinnoh.route-212', 'sinnoh', 45, 'route', 'Rota 212', 'Lama, chuva e, no fim, os jardins de uma mansão cheia de troféus.', null, 'wild', 3, 3, true),
  ('sinnoh.route-210-north', 'sinnoh', 46, 'route', 'Rota 210 — Norte', 'Com os Psyduck curados pelo remédio de Cynthia, resta atravessar a neblina.', null, 'wild', 4, 3, true),
  ('sinnoh.celestic-town', 'sinnoh', 47, 'story', 'Celestic Town', 'Nas ruínas da vila mais antiga de Sinnoh, o chefe da Equipe Galáctica finalmente se apresenta.', 'Cyrus', 'trainer', 4, 1, false),
  ('sinnoh.fuego-ironworks', 'sinnoh', 48, 'route', 'Fuego Ironworks', 'Uma siderúrgica escondida rio abaixo, quente o bastante para atrair Pokémon de fogo.', null, 'wild', 3, 2, true),
  ('sinnoh.route-218', 'sinnoh', 49, 'route', 'Rota 218', 'Agora dá para atravessar a água a oeste de Jubilife e chegar ao porto.', null, 'wild', 4, 2, true),
  ('sinnoh.canalave-city', 'sinnoh', 50, 'story', 'Canalave City', 'Cidade portuária dividida por um canal, com a maior biblioteca de Sinnoh.', null, 'milestone', 3, 1, false),
  ('sinnoh.rival-canalave', 'sinnoh', 51, 'rival', 'Barry na ponte de Canalave', 'Barry espera no meio da ponte. Ninguém passa sem batalhar.', 'Barry', 'rival', 4, 1, false),
  ('sinnoh.canalave-gym', 'sinnoh', 52, 'gym', 'Ginásio de Canalave', 'Byron, pai de Roark, defende o ginásio com uma muralha de Pokémon de aço.', 'Byron', 'gymLeader', 4, 1, false),
  ('sinnoh.iron-island', 'sinnoh', 53, 'route', 'Iron Island', 'Uma mina abandonada no mar. Riley treina ali e aceita companhia.', null, 'trainer', 4, 3, true),
  ('sinnoh.canalave-library', 'sinnoh', 54, 'story', 'Biblioteca de Canalave', 'Entre lendas sobre os três lagos, o chão treme. Algo explodiu no Lago Valor.', null, 'milestone', 3, 1, false),
  ('sinnoh.lake-valor', 'sinnoh', 55, 'story', 'Lake Valor', 'O lago foi drenado pela explosão. O comandante Saturn ficou para garantir o serviço.', 'Saturn', 'trainer', 4, 1, false),
  ('sinnoh.lake-verity-galactic', 'sinnoh', 56, 'story', 'Retorno ao Lake Verity', 'A Equipe Galáctica chegou ao lago perto de casa. Mars quer revanche.', 'Mars', 'trainer', 4, 1, false),
  ('sinnoh.route-211', 'sinnoh', 57, 'route', 'Rota 211', 'Uma trilha de montanha que leva de Eterna de volta ao Monte Coronet.', null, 'wild', 4, 2, true),
  ('sinnoh.mt-coronet-north', 'sinnoh', 58, 'route', 'Mt. Coronet — travessia norte', 'Túneis gelados cortam a montanha até o extremo norte de Sinnoh.', null, 'wild', 4, 3, true),
  ('sinnoh.route-216', 'sinnoh', 59, 'route', 'Rota 216', 'Neve até o joelho e Pokémon que só vivem no frio.', null, 'wild', 4, 3, true),
  ('sinnoh.route-217', 'sinnoh', 60, 'route', 'Rota 217', 'Uma nevasca permanente. Mal dá para ver a cabana no meio do caminho.', null, 'wild', 4, 3, true),
  ('sinnoh.acuity-lakefront', 'sinnoh', 61, 'story', 'Acuity Lakefront', 'A margem do terceiro lago está vigiada. Por enquanto, só resta seguir para a cidade.', null, 'milestone', 3, 1, false),
  ('sinnoh.snowpoint-city', 'sinnoh', 62, 'story', 'Snowpoint City', 'A cidade mais ao norte de Sinnoh, com um templo antigo fechado a visitantes.', null, 'milestone', 3, 1, false),
  ('sinnoh.snowpoint-gym', 'sinnoh', 63, 'gym', 'Ginásio de Snowpoint', 'Candice é pura concentração, e os Pokémon de gelo dela não dão espaço para erro.', 'Candice', 'gymLeader', 5, 1, false),
  ('sinnoh.lake-acuity', 'sinnoh', 64, 'story', 'Lake Acuity', 'Você chega tarde: Jupiter já levou o guardião do lago e deixou Barry derrotado.', null, 'milestone', 4, 1, false),
  ('sinnoh.galactic-hq', 'sinnoh', 65, 'story', 'Sede Galáctica em Veilstone', 'Corredores, teleportes e capangas em cada sala do quartel-general.', null, 'trainer', 4, 3, false),
  ('sinnoh.galactic-hq-cyrus', 'sinnoh', 66, 'story', 'O escritório de Cyrus', 'Cyrus explica com calma o mundo que pretende criar — e testa você pessoalmente.', 'Cyrus', 'trainer', 5, 1, false),
  ('sinnoh.galactic-hq-saturn', 'sinnoh', 67, 'story', 'Laboratório Galáctico', 'Os três guardiões dos lagos estão presos nas máquinas. Saturn guarda a sala.', 'Saturn', 'trainer', 5, 1, false),
  ('sinnoh.mt-coronet-summit', 'sinnoh', 68, 'route', 'Mt. Coronet — subida ao cume', 'Neve, cachoeiras e paredões até o ponto mais alto de Sinnoh.', null, 'wild', 4, 3, true),
  ('sinnoh.spear-pillar', 'sinnoh', 69, 'story', 'Spear Pillar', 'Entre as colunas do cume, Mars e Jupiter barram o caminho. Barry luta ao seu lado.', 'Mars e Jupiter', 'trainer', 5, 1, false),
  ('sinnoh.distortion-world', 'sinnoh', 70, 'story', 'Distortion World', 'Um mundo ao avesso, onde o chão flutua e a gravidade muda de direção.', null, 'milestone', 5, 1, false),
  ('sinnoh.distortion-world-cyrus', 'sinnoh', 71, 'story', 'Cyrus no Distortion World', 'Sem mais ninguém entre vocês, Cyrus defende seu mundo sem emoções pela última vez.', 'Cyrus', 'trainer', 5, 1, false),
  ('sinnoh.giratina', 'sinnoh', 72, 'story', 'Giratina', 'O Pokémon que governa o mundo distorcido avança, furioso com a invasão.', null, 'milestone', 5, 1, false),
  ('sinnoh.sendoff-spring', 'sinnoh', 73, 'story', 'Sendoff Spring', 'De volta ao mundo real, num lago escondido que ninguém sabia que existia.', null, 'milestone', 3, 1, false),
  ('sinnoh.route-222', 'sinnoh', 74, 'route', 'Rota 222', 'Praia e pescadores no trecho final até a cidade do sol.', null, 'wild', 4, 3, true),
  ('sinnoh.sunyshore-city', 'sinnoh', 75, 'story', 'Sunyshore City', 'Passarelas solares cobrem a cidade. O líder, entediado, observa tudo do farol.', null, 'milestone', 4, 1, false),
  ('sinnoh.sunyshore-gym', 'sinnoh', 76, 'gym', 'Ginásio de Sunyshore', 'Volkner, o líder mais forte de Sinnoh, só quer um desafiante que valha a pena.', 'Volkner', 'gymLeader', 5, 1, false),
  ('sinnoh.route-223', 'sinnoh', 77, 'route', 'Rota 223', 'Mar aberto ao norte de Sunyshore, cheio de nadadores e rochedos.', null, 'trainer', 4, 3, true),
  ('sinnoh.victory-road', 'sinnoh', 78, 'route', 'Victory Road', 'A última caverna antes da Liga, reservada a quem tem as oito insígnias.', null, 'wild', 5, 4, true),
  ('sinnoh.rival-pokemon-league', 'sinnoh', 79, 'rival', 'Barry na Liga Pokémon', 'Barry chegou primeiro, claro. Um último duelo antes da Elite dos Quatro.', 'Barry', 'rival', 5, 1, false),
  ('sinnoh.elite-four-aaron', 'sinnoh', 80, 'story', 'Elite dos Quatro — Aaron', 'O primeiro da Elite cresceu entre Pokémon inseto e os leva muito a sério.', 'Aaron', 'trainer', 5, 1, false),
  ('sinnoh.elite-four-bertha', 'sinnoh', 81, 'story', 'Elite dos Quatro — Bertha', 'Uma senhora gentil cujos Pokémon de terra não têm nada de gentis.', 'Bertha', 'trainer', 5, 1, false),
  ('sinnoh.elite-four-flint', 'sinnoh', 82, 'story', 'Elite dos Quatro — Flint', 'Flint luta como fala: alto, quente e sem pausa.', 'Flint', 'trainer', 5, 1, false),
  ('sinnoh.elite-four-lucian', 'sinnoh', 83, 'story', 'Elite dos Quatro — Lucian', 'Lucian fecha o livro que estava lendo. Os Pokémon psíquicos dele já sabem o que fazer.', 'Lucian', 'trainer', 5, 1, false),
  ('sinnoh.champion-cynthia', 'sinnoh', 84, 'story', 'Campeã Cynthia', 'Ela ajudou você durante toda a jornada. Agora é o último obstáculo dela.', 'Cynthia', 'trainer', 5, 1, false),
  ('sinnoh.fight-area', 'sinnoh', 85, 'story', 'Fight Area', 'Mal o barco atraca, Barry puxa você para uma batalha em dupla contra Flint e Volkner.', 'Flint e Volkner', 'trainer', 5, 1, false),
  ('sinnoh.route-225', 'sinnoh', 86, 'route', 'Rota 225', 'Trilhas íngremes e treinadores veteranos na ilha do nordeste.', null, 'wild', 5, 3, true),
  ('sinnoh.survival-area', 'sinnoh', 87, 'story', 'Survival Area', 'Um acampamento de treinadores durões. Buck fala de um tesouro no vulcão.', null, 'milestone', 4, 1, false),
  ('sinnoh.route-227', 'sinnoh', 88, 'route', 'Rota 227', 'Cinzas caem do céu no caminho que sobe até Stark Mountain.', null, 'wild', 5, 3, true),
  ('sinnoh.stark-mountain', 'sinnoh', 89, 'route', 'Stark Mountain', 'Lava, rochas soltas e Pokémon fortes no interior do vulcão. Buck vai junto.', null, 'wild', 5, 3, true),
  ('sinnoh.stark-mountain-galactic', 'sinnoh', 90, 'story', 'O que restou da Equipe Galáctica', 'Charon quer despertar o vulcão. Mars e Jupiter o acompanham pela última vez.', 'Mars e Jupiter', 'trainer', 5, 1, false),
  ('sinnoh.heatran', 'sinnoh', 91, 'story', 'Heatran', 'No fundo da cratera, o Pokémon do vulcão acorda.', null, 'milestone', 5, 1, false),
  ('sinnoh.route-229', 'sinnoh', 92, 'route', 'Rota 229', 'Mata fechada e treinadores de elite a caminho da Resort Area.', null, 'wild', 5, 3, true),
  ('sinnoh.resort-area', 'sinnoh', 93, 'story', 'Resort Area', 'Vilas à beira-mar e, enfim, um lugar para descansar.', null, 'milestone', 3, 1, false),
  ('sinnoh.rival-survival-area', 'sinnoh', 94, 'rival', 'Barry, mais uma vez', 'Barry agora treina todo fim de semana na Survival Area e nunca recusa uma revanche.', 'Barry', 'rival', 5, 1, false),
  ('sinnoh.lake-guardians', 'sinnoh', 95, 'story', 'Os guardiões dos lagos', 'Uxie, Mesprit e Azelf voltaram para casa. Cada um aceita um último encontro.', null, 'milestone', 5, 1, false),
  ('sinnoh.spear-pillar-legends', 'sinnoh', 96, 'story', 'Dialga e Palkia', 'De volta ao cume, com as orbes certas, os senhores do tempo e do espaço respondem.', null, 'milestone', 5, 1, false)
